attributes.reducer:
(
  $s := $state; $a := $action; $t := $a.type;
  $W := $s.W; $H := $s.H;
  $opp := {"up": "down", "down": "up", "left": "right", "right": "left"};
  $dirOf := {"up": "up", "down": "down", "left": "left", "right": "right",
             "swipe-up": "up", "swipe-down": "down", "swipe-left": "left", "swipe-right": "right"};
  $render := function($st) {
    $map([0..($W * $H - 1)], function($i) { (
      $x := $i % $W; $y := $floor($i / $W);
      $x = $st.snake[0].x and $y = $st.snake[0].y ? 2 :
      $count($st.snake[x = $x and y = $y]) > 0 ? 1 :
      $x = $st.food.x and $y = $st.food.y ? 3 : 0
    ) })
  };
  $newFood := function($body, $seed) { (
    $free := $filter([0..($W * $H - 1)], function($i) { $count($body[x = $i % $W and y = $floor($i / $W)]) = 0 });
    $r := $rand($seed);
    $k := $free[$floor($r.value * $count($free))];
    {"food": {"x": $k % $W, "y": $floor($k / $W)}, "seed": $r.seed}
  ) };
  $fresh := function($st) { (
    $f := $newFood($st.start, $st.seed);
    $merge([$st, {"snake": $st.start, "dir": "right", "queued": "right", "food": $f.food, "seed": $f.seed,
      "score": 0, "speed": $st.initSpeed, "phase": "play", "running": true, "msg": ""}])
  ) };
  $show := function($st) { $merge([$st, {"cells": $render($st)}]) };
  $d := $lookup($dirOf, $t);
  $t = "init" ? $show($merge([$s, {"snake": $s.start, "phase": "ready", "running": false, "msg": $s.txt.ready}])) :
  $t = "restart" ? $show($fresh($s)) :
  $t = "toggle" ? (
    $s.phase = "play" ? $merge([$s, {"phase": "pause", "running": false, "msg": $s.txt.paused}]) :
    $s.phase = "pause" ? $merge([$s, {"phase": "play", "running": true, "msg": ""}]) :
    $show($fresh($s))
  ) :
  $d ? (
    $s.phase = "ready" or $s.phase = "over" ? $show($merge([$fresh($s), {"queued": $d = "left" ? "right" : $d}])) :
    $d != $lookup($opp, $s.dir) ? $merge([$s, {"queued": $d}]) : $s
  ) :
  $t = "tick" and $s.phase = "play" ? (
    $dir := $s.queued;
    $h := $s.snake[0];
    $nx := $h.x + ($dir = "right" ? 1 : $dir = "left" ? -1 : 0);
    $ny := $h.y + ($dir = "down" ? 1 : $dir = "up" ? -1 : 0);
    $len := $count($s.snake);
    $moving := $len > 1 ? $s.snake[[0..($len - 2)]] : [];
    $hit := $nx < 0 or $ny < 0 or $nx >= $W or $ny >= $H or $count($moving[x = $nx and y = $ny]) > 0;
    $hit
      ? $merge([$s, {"phase": "over", "running": false, "best": $max([$s.best, $s.score]),
          "msg": $s.txt.over & " " & $string($s.score)}])
      : (
        $eat := $nx = $s.food.x and $ny = $s.food.y;
        $body := $append([{"x": $nx, "y": $ny}], $eat ? $s.snake : $moving);
        $f := $eat ? $newFood($body, $s.seed) : {"food": $s.food, "seed": $s.seed};
        $show($merge([$s, {"snake": $body, "dir": $dir, "food": $f.food, "seed": $f.seed,
          "score": $s.score + ($eat ? 10 : 0),
          "speed": $eat ? $max([60, $s.speed - 4]) : $s.speed}]))
      )
  ) :
  $s
)
